param([Parameter(Mandatory=$true)][string]$OutputDirectory,[Parameter(Mandatory=$true)][string]$ResearchDirectory)
$ErrorActionPreference='Stop';if($PSVersionTable.PSVersion.Major -lt 7){throw 'Use pwsh.exe'}
$mwCFRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$mwCFOut=[IO.Path]::GetFullPath($OutputDirectory);$mwCFResearch=(Resolve-Path -LiteralPath $ResearchDirectory).Path;$mwCFAllowed=Join-Path $mwCFRoot 'reports/m4-crt-control'
if(-not $mwCFOut.StartsWith($mwCFAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase) -or -not $mwCFResearch.StartsWith($mwCFAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Private native control evidence required'}
$mwCFName=Split-Path $mwCFOut -Leaf;if($mwCFName -notmatch '^[a-z][a-z0-9-]{0,63}$' -or $mwCFName -match '^(con|prn|aux|nul|com[0-9]|lpt[0-9])$'){throw 'Fresh simple native control name'}
$mwCFBuilds=[ordered]@{O0=(Join-Path $mwCFRoot "build/m4-crt-control-$mwCFName-O0");O2=(Join-Path $mwCFRoot "build/m4-crt-control-$mwCFName-O2")};if((Test-Path -LiteralPath $mwCFOut) -or @($mwCFBuilds.Values|Where-Object {Test-Path -LiteralPath $_}).Count){throw 'Fresh native control report/build required'}
function Get-MWCFHash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
$mwCFCWReview=Join-Path $mwCFRoot 'reports/m4-guest-cw/independent-review-r1/pins.json';if((Get-MWCFHash $mwCFCWReview) -ne 'b78231bb570ec0e89e27fb5f4fc9c6b5d77335a8279d3362600e5b683c643087'){throw 'Exact independently accepted bounded CW transfer gate required'}
$mwCFSources=[ordered]@{};foreach($mwCFFile in @(Get-ChildItem -LiteralPath $PSScriptRoot -File -Recurse;Get-Item -LiteralPath (Join-Path $PSScriptRoot '../m4-crt/probe_common.hpp'),(Join-Path $PSScriptRoot '../m4-crt/probe_io.hpp'),(Join-Path $PSScriptRoot '../m4-guest-cw/guest_cw.hpp'),(Join-Path $PSScriptRoot '../m4-guest-cw/guest_cw.cpp'),(Join-Path $mwCFRoot 'runtime/memory/guest_memory.cpp'),(Join-Path $mwCFRoot 'runtime/memory/guest_memory.hpp'),(Join-Path $mwCFRoot 'runtime/core/guest_address.hpp'),(Join-Path $mwCFRoot 'local/tools/remill-v6.0.1/remill-6.0.1/include/remill/Arch/X86/Runtime/State.h'),(Join-Path $mwCFResearch 'probe_spec.hpp'),(Join-Path $mwCFResearch 'replay_spec.hpp');Get-ChildItem -LiteralPath (Join-Path $mwCFRoot 'local/tools/remill-v6.0.1/remill-6.0.1/include/remill/Arch/Runtime') -File -Recurse)|Where-Object {$_.FullName -notmatch '__pycache__'}|Sort-Object FullName){$mwCFSources[$mwCFFile.FullName]=Get-MWCFHash $mwCFFile.FullName}
New-Item -ItemType Directory $mwCFOut|Out-Null;$mwCFCopies=[Collections.Generic.List[object]]::new();foreach($mwCFPath in $mwCFSources.Keys){$mwCFCopy=Join-Path (Join-Path $mwCFOut 'sources') ([IO.Path]::GetRelativePath($mwCFRoot,$mwCFPath));New-Item -ItemType Directory -Force -Path (Split-Path $mwCFCopy)|Out-Null;Copy-Item -LiteralPath $mwCFPath -Destination $mwCFCopy;if((Get-MWCFHash $mwCFCopy) -ne $mwCFSources[$mwCFPath]){throw 'Exact literal native control sources'};$mwCFCopies.Add([ordered]@{original_path=$mwCFPath;preserved_path=$mwCFCopy;sha256=$mwCFSources[$mwCFPath]})}
$mwCFCommands=[Collections.Generic.List[object]]::new()
function Invoke-MWCF([string]$Program,[string[]]$Arguments,[string]$Log){[IO.File]::WriteAllText($Log,'');$mwCFSaved=$ErrorActionPreference;$ErrorActionPreference='Continue';try{& $Program @Arguments 2>&1|Tee-Object -FilePath $Log;$mwCFExit=$LASTEXITCODE}finally{$ErrorActionPreference=$mwCFSaved};$mwCFCommands.Add([ordered]@{program=$Program;arguments=$Arguments;exit_code=$mwCFExit;log_path=$Log;log_sha256=(Get-MWCFHash $Log)});if($mwCFExit -ne 0){throw "Native control tool failed $Program exit=$mwCFExit"}}
$mwCFVS='C:/Program Files/Microsoft Visual Studio/18/Community';$mwCFLLVM=Join-Path $mwCFRoot 'local/tools/llvm-21.1.8/clang+llvm-21.1.8-x86_64-pc-windows-msvc';$mwCFPassed=$false;$mwCFFailure=$null;$mwCFWorkers=[ordered]@{}
try{
 Import-Module (Join-Path $mwCFVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll');Enter-VsDevShell -VsInstallPath $mwCFVS -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64'|Out-Null
 $mwCFCMake=Join-Path $mwCFVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/cmake.exe';$mwCFNinja=Join-Path $mwCFVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/Ninja/ninja.exe';$env:PATH="$mwCFLLVM/bin;$(Split-Path $mwCFNinja);$env:PATH";$mwCFTemp=Join-Path $mwCFOut 'compiler-temp';New-Item -ItemType Directory $mwCFTemp|Out-Null;$env:TEMP=$mwCFTemp;$env:TMP=$mwCFTemp;$env:TMPDIR=$mwCFTemp
 $mwCFHost=Join-Path $mwCFResearch 'host.ll';if((Get-MWCFHash $mwCFHost) -ne '49e25a2cd2f9279970fac099141a08742ab678eb9b041be6b1368effc55ea5a9'){throw 'Exact complete static host provider IR required'}
 Invoke-MWCF (Join-Path $mwCFLLVM 'bin/opt.exe') @('-passes=verify','-disable-output',$mwCFHost) (Join-Path $mwCFOut 'verify.log')
 foreach($mwCFLevel in @('O0','O2')){
  $mwCFInput=$mwCFHost;if($mwCFLevel -eq 'O2'){$mwCFInput=Join-Path $mwCFOut 'host-O2.ll';Invoke-MWCF (Join-Path $mwCFLLVM 'bin/opt.exe') @('-passes=default<O2>','-S',$mwCFHost,'-o',$mwCFInput) (Join-Path $mwCFOut 'opt-O2.log')}
  $mwCFObject=Join-Path $mwCFOut "native-$mwCFLevel.obj";Invoke-MWCF (Join-Path $mwCFLLVM 'bin/llc.exe') @('-filetype=obj',"-$mwCFLevel",$mwCFInput,'-o',$mwCFObject) (Join-Path $mwCFOut "llc-$mwCFLevel.log")
  Invoke-MWCF (Join-Path $mwCFLLVM 'bin/llvm-nm.exe') @('--undefined-only',$mwCFObject) (Join-Path $mwCFOut "symbols-$mwCFLevel.txt")
  $mwCFFlags=if($mwCFLevel -eq 'O0'){'/Od /DNDEBUG'}else{'/O2 /DNDEBUG'}
  Invoke-MWCF $mwCFCMake @('-G','Ninja','-S',(Join-Path $PSScriptRoot 'native'),'-B',$mwCFBuilds[$mwCFLevel],'-DCMAKE_BUILD_TYPE=Release',"-DCMAKE_CXX_COMPILER=$mwCFLLVM/bin/clang-cl.exe","-DCMAKE_CXX_FLAGS_RELEASE=$mwCFFlags","-DMW34_CONTROL_INCLUDE=$mwCFResearch","-DMW34_CONTROL_OBJECT=$mwCFObject") (Join-Path $mwCFOut "configure-$mwCFLevel.log")
  Invoke-MWCF $mwCFCMake @('--build',$mwCFBuilds[$mwCFLevel],'--parallel','8','--verbose') (Join-Path $mwCFOut "build-$mwCFLevel.log")
  $mwCFWorkers[$mwCFLevel]=Join-Path $mwCFBuilds[$mwCFLevel] 'mw34_control_native.exe';Invoke-MWCF $mwCFWorkers[$mwCFLevel] @('--check-hash') (Join-Path $mwCFOut "hash-$mwCFLevel.log")
 }
 foreach($mwCFPath in $mwCFSources.Keys){if((Get-MWCFHash $mwCFPath) -ne $mwCFSources[$mwCFPath]){throw 'Native control source changed during build'}};$mwCFPassed=$true
}catch{$mwCFFailure=$_.Exception.Message;$_|Out-String|Set-Content -LiteralPath (Join-Path $mwCFOut 'failure.txt');throw}finally{
 $mwCFArtifacts=[ordered]@{};foreach($mwCFFile in @(Get-ChildItem -LiteralPath $mwCFOut -File -Recurse;Get-ChildItem -LiteralPath $mwCFResearch -File -Recurse;foreach($mwCFDir in $mwCFBuilds.Values){if(Test-Path -LiteralPath $mwCFDir){Get-ChildItem -LiteralPath $mwCFDir -File -Recurse|Where-Object {$_.Extension -in @('.exe','.obj','.lib','.txt','.cmake','.json') -or $_.Name -in @('build.ninja','rules.ninja','.ninja_log')}}})|Where-Object {$_.FullName -notmatch 'compiler-temp'}|Sort-Object FullName){$mwCFArtifacts[$mwCFFile.FullName]=Get-MWCFHash $mwCFFile.FullName}
 $mwCFTools=[ordered]@{};foreach($mwCFTool in @($mwCFCMake,$mwCFNinja,(Get-Process -Id $PID).Path,(Join-Path $mwCFVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll'),(Get-Command rc.exe -ErrorAction SilentlyContinue).Source)+@('clang-cl.exe','llvm-lib.exe','lld-link.exe','llvm-mt.exe','opt.exe','llc.exe','llvm-nm.exe'|ForEach-Object {Join-Path $mwCFLLVM "bin/$_"})){if($mwCFTool -and (Test-Path -LiteralPath $mwCFTool)){$mwCFTools[$mwCFTool]=Get-MWCFHash $mwCFTool}}
 [ordered]@{passed=$mwCFPassed;failure=$mwCFFailure;scope='Four actual compiled static provider definitions and bounded CW bridge; original/native comparison pending';source_files=$mwCFSources;literal_source_copies=@($mwCFCopies);tool_files=$mwCFTools;artifacts=$mwCFArtifacts;commands=@($mwCFCommands);workers=$mwCFWorkers;CW_independent_pins_path=$mwCFCWReview;CW_independent_pins_sha256=(Get-MWCFHash $mwCFCWReview);whole_M4_complete=$false}|ConvertTo-Json -Depth 16|Set-Content -Encoding utf8 -LiteralPath (Join-Path $mwCFOut 'build.json')
}
